// File: notification-client/src/components/DeliveryDetails.tsx

import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { io } from "socket.io-client";

interface Delivery {
  _id: string;
  customerId: string;
  driverId?: string;
  address: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
const socket = io("http://localhost:5000"); // Connect to backend socket

export default function DeliveryDetails() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [delivery, setDelivery] = useState<Delivery | null>(null);
  const [driverPosition, setDriverPosition] = useState<{ lat: number; lng: number } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!id) {
      setError("❗ No delivery ID provided in URL.");
      setLoading(false);
      return;
    }

    axios
      .get(`${API_BASE_URL}/api/delivery/${id}`)
      .then((res) => {
        setDelivery(res.data);
        setDriverPosition(res.data.location); // Initial driver location
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching delivery details:", err);
        setError("❌ Failed to fetch delivery details");
        setLoading(false);
      });

    // Listen for real-time driver location updates
    socket.on("driverLocationUpdate", (data) => {
      if (data.deliveryId === id) {
        setDriverPosition({ lat: data.lat, lng: data.lng });
      }
    });

    return () => {
      socket.off("driverLocationUpdate");
    };
  }, [id]);

  if (loading) return <div>Loading...</div>;
  if (error || !delivery) return <div>{error || "Delivery not found"}</div>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>📦 Delivery Details</h2>

      <p><strong>Customer ID:</strong> {delivery.customerId}</p>
      <p><strong>Status:</strong> {delivery.status}</p>
      <p><strong>Driver ID:</strong> {delivery.driverId || "Not assigned"}</p>
      <p><strong>Delivery Address:</strong> {delivery.address}</p>

      <div style={{ marginTop: "20px", display: "flex", gap: "1rem" }}>
        <button
          onClick={() => navigate("/")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#6c757d",
            color: "#fff",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          ← Back to Dashboard
        </button>
      </div>

      {/* Live Google Map */}
      <div style={{ marginTop: "30px" }}>
        <h3>🗺️ Live Delivery Tracking:</h3>
        <iframe
          title="Live Driver Tracking Map"
          width="100%"
          height="450"
          frameBorder="0"
          style={{ border: 0 }}
          src={`https://maps.google.com/maps?q=${driverPosition?.lat},${driverPosition?.lng}&z=15&output=embed`}
          allowFullScreen
        />
      </div>
    </div>
  );
}
